-- Inserimento dati della tabella ServizioErogato

INSERT INTO ServizioErogato (ID_ServizioErogato, NomeServizioErogato, DescrizioneServizioErogato, NumeroMacroArea, CategoriaRilevanzaAttribuita, MotivazioneCategoria, RTO_SE, RPO_SE, Responsabile_SE)
VALUES
    (101, 'Telecomando e Controllo TT&C', 'Invio di comandi di assetto e orbita ai satelliti e ricezione dello stato di salute', 1, 4, 'Il blocco prolungato causa la perdita del controllo del satellite con rischio rientro atmosferico', '15m', '0m', 2),
    (102, 'Calcolo Dinamica di Volo', 'Determinazione precisa delle orbite e pianificazione delle manovre anti-collisione', 1, 4, 'Rischio di impatto con detriti spaziali o altri satelliti operativi', '30m', '5m', 12),
    (103, 'Distribuzione Dati IoT Orbitali', 'Ricezione dai satelliti e instradamento dei messaggi dei sensori IoT di terra', 2, 3, 'Disservizio commerciale con ritardi nella ricezione dei dati ambientali globali', '4h', '1h', 14),
    (104, 'Elaborazione Immagini Satellitari', 'Processamento dei dati grezzi provenienti dai payload ottici e SAR in mappe georeferenziate', 2, 3, 'Ritardo nella consegna dei contratti commerciali di osservazione', '12h', '2h', 3),
    (105, 'Manovre di Collision Avoidance', 'Automazione delle procedure di emergenza per la deviazione dell''orbita', 1, 4, 'Criticità assoluta per l''integrità fisica degli asset spaziali', '10m', '0m', 9),
    (106, 'Scheduling Contatti Ground Station', 'Pianificazione delle finestre di passaggio dei satelliti sopra le antenne di terra', 1, 3, 'La perdita dello schedule salta i passaggi di scarico dati utili', '2h', '15m', 4),
    (107, 'Frequenze e Licenze Spaziali (DB)', 'Registro delle assegnazioni delle frequenze radio autorizzate dalle agenzie nazionali', 8, 2, 'Consultazione interna per conformità, non blocca le operazioni in tempo reale', '24h', '24h', 5),
    (108, 'Consegna Immagini d''Emergenza (Disastri)', 'Canale prioritario per la fornitura di mappe satellitari a scopi di protezione civile', 5, 4, 'Impatto umanitario e di sicurezza nazionale in caso di calamità naturali', '1h', '10m', 18),
    (109, 'Monitoraggio Meteo Spaziale (Solar)', 'Raccolta dati sulle tempeste solari e radiazioni per proteggere l''elettronica di bordo', 1, 3, 'Necessario per decidere la messa in modalità provvisoria (safe mode) dei satelliti', '2h', '30m', 2),
    (110, 'Cyber Security Monitoraggio Flussi Link', 'Controllo e rilevamento anomalie di cifratura sul link radio terra-spazio', 1, 4, 'Rischio di dirottamento ostile (hijacking) dei satelliti della costellazione', '5m', '0m', 15),
    (111, 'Pianificazione Turni MOC', 'Gestione dei turni h24 degli operatori di volo nella sala controllo principale', 7, 2, 'Gestibile temporaneamente estendendo i turni correnti o con registri manuali', '8h', '24h', 11),
    (112, 'Portale Clienti B2B Tasking', 'Interfaccia web tramite cui i clienti richiedono il puntamento del satellite su un''area', 5, 2, 'Rallenta le nuove richieste ma non influisce sui puntamenti già pianificati', '24h', '12h', 18),
    (113, 'Telemetria Storica ed Trend Analysis', 'Analisi a lungo termine del degrado dei pannelli solari e delle batterie dei satelliti', 8, 1, 'Attività di analisi differibile nel tempo, nessun impatto real-time', '168h', '168h', 10),
    (114, 'Ponti Radio Inter-Stazione Ground', 'Collegamenti ridondati di rete per unire le antenne sparse nel globo al centro MOC', 1, 4, 'L''isolamento di una stazione di terra impedisce il contatto radio con i satelliti', '15m', '0m', 19),
    (115, 'Logistica Spedizioni Terminali', 'Pianificazione e tracciamento dei gateway di terra da spedire ai clienti IoT', 4, 1, 'Attività puramente commerciale e logistica con scadenze flessibili', '72h', '48h', 13),
    (116, 'Contabilità e Contratti Lanciatori', 'Gestione dei pagamenti e dei contratti assicurativi per i prossimi voli di posizionamento', 6, 1, 'Impatto amministrativo dilazionabile senza impatti sulle operazioni in orbita', '72h', '24h', 16),
    (117, 'Monitoraggio Qualità del Segnale RF', 'Analisi delle interferenze sullo spettro radio durante i passaggi chiave', 2, 2, 'Inadempienza contrattuale sui livelli di segnale ma non interrompe i comandi', '12h', '12h', 6),
    (118, 'Controllo Accessi Fisici Ground Station', 'Sistemi di sicurezza e telecamere intorno ai radar e antenne paraboliche', 1, 2, 'Presidiabile fisicamente da personale di sorveglianza locale in caso di guasto', '24h', '24h', 1),
    (119, 'Sito Web Istituzionale e Tracking', 'Mappa pubblica per tracciare la posizione dei satelliti a scopo di PR', 9, 1, 'Impatto reputazionale minimo, non influisce sul volo dei satelliti', '48h', '48h', 18),
    (120, 'Conservazione Sostitutiva Log Missione', 'Archiviazione certificata dei comandi inviati nello spazio per obblighi assicurativi', 5, 1, 'Obbligo di legge senza requisiti di disponibilità o accesso immediato', '168h', '168h', 20);

